{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'auth', 'storage', 'public')
ORDER BY table_schema, table_name;
"}

{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_type = 'BASE TABLE'
ORDER BY table_schema, table_name;
"}

{"query": "
DROP TABLE IF EXISTS employees.employee_retention_analysis;
CREATE TABLE employees.employee_retention_analysis (
    department_name      VARCHAR(100),
    total_employees_ever INTEGER,
    current_employees    INTEGER,
    former_employees     INTEGER,
    retention_rate       DECIMAL(6,2)
);
"}

{"query": "
DROP TABLE IF EXISTS employees.high_risk_employees;
CREATE TABLE employees.high_risk_employees (
    employee_id        BIGINT,
    full_name          VARCHAR(200),
    current_department VARCHAR(100),
    tenure_days        INTEGER,
    current_salary     INTEGER,
    risk_category      VARCHAR(20)
);
"}

{"query": "
DROP TABLE IF EXISTS employees.turnover_trend_analysis;
CREATE TABLE employees.turnover_trend_analysis (
    departure_year   INTEGER,
    departures_count INTEGER,
    avg_tenure_days  DECIMAL(10,2),
    avg_final_salary DECIMAL(12,2)
);
"}

{"query": "
-- Check some sample high_risk_employees records
SELECT employee_id, full_name, current_department, tenure_days, current_salary, risk_category
FROM employees.high_risk_employees
LIMIT 10;
"}
